extension Ws.Auth.User {
    /// Delete a user. Without confirm the reply is a refusal with data.code 'user_delete' and the question to ask. The
    /// user's vaults are destroyed unless transfer_to names who gets them.
    public enum Delete: WsRequest {
        public static let command = WsCommand.authUserDelete

        public struct Payload: Codable, Hashable, Sendable {
            /// Minimum 0.
            public var id: Int64
            public var confirm: Bool?
            /// Minimum 0. nil omits it, `.null` sends null.
            public var transferTo: Nullable<Int64>?

            public init(id: Int64, confirm: Bool? = nil, transferTo: Nullable<Int64>? = nil) {
                self.id = id
                self.confirm = confirm
                self.transferTo = transferTo
            }

            enum CodingKeys: String, CodingKey {
                case id
                case confirm
                case transferTo = "transfer_to"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                id = try container.decode(Int64.self, forKey: .id)
                confirm = try container.decodeIfPresent(Bool.self, forKey: .confirm)
                transferTo = container.contains(.transferTo)
                    ? try container.decode(Nullable<Int64>.self, forKey: .transferTo) : nil
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(id, forKey: .id)
                try container.encodeIfPresent(confirm, forKey: .confirm)
                try container.encodeIfPresent(transferTo, forKey: .transferTo)
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            /// Minimum 0.
            public var userID: Int64

            public init(userID: Int64) {
                self.userID = userID
            }

            enum CodingKeys: String, CodingKey {
                case userID = "user_id"
            }
        }
    }
}

